import type { ReactNode } from 'react';
import './application-shell.css';

type Props = { toolbar: ReactNode; navigation: ReactNode; children: ReactNode; inspector: ReactNode; inspectorWidth?: number; onInspectorResize?: (width: number) => void };

export function ApplicationShell({ toolbar, navigation, children, inspector, inspectorWidth = 320, onInspectorResize }: Props) {
  function resize(event: React.KeyboardEvent<HTMLDivElement>) {
    if (!onInspectorResize) return;
    const delta = event.key === 'ArrowLeft' ? 16 : event.key === 'ArrowRight' ? -16 : 0;
    if (delta) { event.preventDefault(); onInspectorResize(Math.min(520, Math.max(240, inspectorWidth + delta))); }
  }
  return <div className="appShell" style={{ '--inspector-width': `${inspectorWidth}px` } as React.CSSProperties}>
    <header className="appToolbar">{toolbar}</header>
    <nav className="appNav" aria-label="Workspace navigation">{navigation}</nav>
    <main className="appWorkspace" id="main-workspace" tabIndex={-1}>{children}</main>
    <div className="inspectorResize" role="separator" aria-label="Resize inspector" aria-orientation="vertical" aria-valuemin={240} aria-valuemax={520} aria-valuenow={inspectorWidth} tabIndex={0} onKeyDown={resize} />
    <aside className="appInspector" aria-label="Inspector">{inspector}</aside>
  </div>;
}

